SELECT COUNT(*) AS count FROM AUD_DEPENDENCY_CONSUMPTION t WHERE (EXISTS (SELECT 1 FROM AUD_PIPELINES_RUN_LOG r JOIN CFG_PIPELINES p ON p.PIPELINE_ID=r.PIPELINE_ID WHERE p.PROJECT_ID=:project_id AND r.STATUS IN ('SUCCESS','FAILED','SKIPPED','CANCELLED') AND r.END_DATE < :cutoff AND r.PIPELINE_RUN_ID=t.PIPELINE_RUN_ID)) AND t.CONSUMED_AT < :cutoff
